/// <summary>
/// desigend from AVA
/// </summary>
public void modified()
{
    FormDataObject   formDataObject = any2Object(this) as FormDataObject;
    FormDataSource   formDataSource = formDataObject.datasource();
    FormRun          formRun = formDataSource.formRun();
    ProdParmRelease  prodParmRelease = formDataSource.cursor(); ;

    next modified();


    formRun.design().controlName('AVASetupButtonProdRunMap').enabled(prodParmRelease.AVAPrintProdRunMap);

    formRun.design().controlName('ProdParmRelease_AVAPrintReferenceRunMap').enabled(prodParmRelease.AVAPrintProdRunMap);
    if (prodParmRelease.AVAPrintProdRunMap == NoYes::No)
    {
        prodParmRelease.AVAPrintReferenceRunMap =  NoYes::No;
    }

}
